import json
from datetime import datetime, timezone

import httpx
from langchain_core.tools import StructuredTool
from lfx.custom.custom_component.component import Component
from lfx.field_typing import Tool
from lfx.io import Output
from pydantic import BaseModel, Field


class YahooStockPriceTool(Component):
    display_name = "Yahoo Finance: cena akcie"
    description = "Nástroj pro agenta: aktuální cena akcie z Yahoo Finance."
    icon = "TrendingUp"
    name = "YahooStockPriceTool"

    inputs = []

    outputs = [
        Output(display_name="Tool", name="tool", method="build_tool"),
    ]

    def build_tool(self) -> Tool:
        class StockPriceArgs(BaseModel):
            ticker: str = Field(..., description="Ticker akcie na Yahoo Finance, např. AAPL, MSFT, CEZ.PR")

        def get_stock_price(ticker: str) -> str:
            symbol = ticker.strip().upper()
            try:
                r = httpx.get(
                    f"https://query1.finance.yahoo.com/v8/finance/chart/{symbol}",
                    params={"range": "5d", "interval": "1d"},
                    headers={"User-Agent": "Mozilla/5.0"},
                    timeout=15,
                )
                payload = r.json()
            except Exception as e:  # noqa: BLE001
                return json.dumps({"ticker": symbol, "error": f"Yahoo Finance nedostupné: {e}"}, ensure_ascii=False)

            chart = payload.get("chart", {})
            if chart.get("error") or not chart.get("result"):
                return json.dumps({"ticker": symbol, "error": "Ticker nenalezen nebo bez dat."}, ensure_ascii=False)

            meta = chart["result"][0].get("meta", {})
            price = meta.get("regularMarketPrice")
            prev = meta.get("chartPreviousClose") or meta.get("previousClose")
            data = {
                "ticker": symbol,
                "name": meta.get("longName") or meta.get("shortName"),
                "price": price,
                "previous_close": prev,
                "currency": meta.get("currency"),
                "day_high": meta.get("regularMarketDayHigh"),
                "day_low": meta.get("regularMarketDayLow"),
                "exchange": meta.get("exchangeName"),
            }
            if meta.get("regularMarketTime"):
                data["as_of"] = datetime.fromtimestamp(meta["regularMarketTime"], tz=timezone.utc).strftime(
                    "%Y-%m-%d %H:%M UTC"
                )
            if price and prev:
                data["change_percent"] = round((price / prev - 1) * 100, 2)
            return json.dumps(data, ensure_ascii=False)

        return StructuredTool.from_function(
            func=get_stock_price,
            name="get_stock_price",
            description="Vrátí aktuální cenu akcie, předchozí uzavírací cenu, denní změnu a měnu "
            "podle tickeru z Yahoo Finance.",
            args_schema=StockPriceArgs,
        )

import json
from collections import defaultdict
from datetime import datetime, timedelta, timezone

import httpx
from langchain_core.tools import StructuredTool
from lfx.custom.custom_component.component import Component
from lfx.field_typing import Tool
from lfx.io import Output
from pydantic import BaseModel, Field


class YahooDividendTool(Component):
    display_name = "Yahoo Finance: dividendy"
    description = "Nástroj pro agenta: výše a historie dividend z Yahoo Finance."
    icon = "Coins"
    name = "YahooDividendTool"

    inputs = []

    outputs = [
        Output(display_name="Tool", name="tool", method="build_tool"),
    ]

    def build_tool(self) -> Tool:
        class DividendArgs(BaseModel):
            ticker: str = Field(..., description="Ticker akcie na Yahoo Finance, např. AAPL, KO, CEZ.PR")
            years: int = Field(5, description="Kolik let historie dividend vrátit (1-20).")

        def get_dividends(ticker: str, years: int = 5) -> str:
            symbol = ticker.strip().upper()
            years = max(1, min(int(years or 5), 20))
            try:
                r = httpx.get(
                    f"https://query1.finance.yahoo.com/v8/finance/chart/{symbol}",
                    params={"range": f"{years}y", "interval": "1mo", "events": "div"},
                    headers={"User-Agent": "Mozilla/5.0"},
                    timeout=15,
                )
                payload = r.json()
            except Exception as e:  # noqa: BLE001
                return json.dumps({"ticker": symbol, "error": f"Yahoo Finance nedostupné: {e}"}, ensure_ascii=False)

            chart = payload.get("chart", {})
            if chart.get("error") or not chart.get("result"):
                return json.dumps({"ticker": symbol, "error": "Ticker nenalezen nebo bez dat."}, ensure_ascii=False)

            result = chart["result"][0]
            meta = result.get("meta", {})
            raw = (result.get("events") or {}).get("dividends") or {}
            payments = sorted(
                (
                    datetime.fromtimestamp(int(d.get("date", ts)), tz=timezone.utc),
                    float(d.get("amount", 0)),
                )
                for ts, d in raw.items()
            )
            price = meta.get("regularMarketPrice")
            data = {"ticker": symbol, "currency": meta.get("currency"), "current_price": price}
            if not payments:
                data["payments"] = []
                data["note"] = "Za zvolené období nebyly nalezeny žádné dividendy."
                return json.dumps(data, ensure_ascii=False)

            year_ago = datetime.now(tz=timezone.utc) - timedelta(days=365)
            ttm = sum(a for d, a in payments if d >= year_ago)
            per_year = defaultdict(float)
            for d, a in payments:
                per_year[str(d.year)] += a

            data.update(
                {
                    "payments": [{"date": d.strftime("%Y-%m-%d"), "amount": round(a, 4)} for d, a in payments],
                    "last_payment": {"date": payments[-1][0].strftime("%Y-%m-%d"), "amount": round(payments[-1][1], 4)},
                    "dividends_last_12_months": round(ttm, 4),
                    "sum_per_year": {y: round(v, 4) for y, v in sorted(per_year.items())},
                }
            )
            if price:
                data["trailing_yield_percent"] = round(ttm / price * 100, 2)
            return json.dumps(data, ensure_ascii=False)

        return StructuredTool.from_function(
            func=get_dividends,
            name="get_dividends",
            description="Vrátí výši dividend akcie: jednotlivé výplaty, poslední výplatu, součet za "
            "posledních 12 měsíců, roční součty a dividendový výnos.",
            args_schema=DividendArgs,
        )
